"""Private study controls; state is queued locally until the Worker confirms receipt."""
import html

CSS = r"""
.unit-grid .study-item{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:12px;align-items:start;padding:14px 16px}.study-kind{display:block;color:var(--muted);font-size:11px;letter-spacing:.04em}.unit-grid h3{color:#294a72;margin:24px 0 2px;font-size:17px}.unit-grid .study-rates{margin:0}.unit-grid .study-rates button{font-size:12px}.unit-grid .study-badge{grid-column:1/-1}.unit-callout{padding:15px 18px;border-left:3px solid #3e6794;background:#edf2f8;border-radius:0 8px 8px 0;display:flex;gap:10px;flex-wrap:wrap}.unit-callout a{font-weight:650}
@media(max-width:600px){.unit-grid .study-item{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}.unit-grid .study-rates{grid-column:1/-1}.unit-grid .study-rates button{padding:4px 10px}.unit-grid .study-badge{margin-left:0}}

.study-tools,.study-bar,.study-rates,.study-filters{display:flex;flex-wrap:wrap;gap:.5rem;align-items:center;margin:.7rem 0}
.today-focus{color:#ad4035}.pattern,.conn,.lesson-nav a{color:#315c8e}
.study-tools input{min-width:12rem;max-width:100%;padding:.55rem;border:1px solid #bdb6ad;border-radius:.4rem}
.study-tools button,.study-bar button,.study-rates button,.study-filters button,.study-choice{font:inherit;background:#fff;border:1px solid #b6b9bb;border-radius:.45rem;padding:.45rem .7rem;cursor:pointer;color:#294a72}
.study-filters button[aria-pressed=true],.study-bar button[aria-pressed=true]{background:#294a72;color:white;border-color:#294a72}
.study-list{display:grid;gap:.55rem}.study-item{padding:.8rem;border:1px solid #e3ded6;border-radius:.6rem;background:#fff}.study-item p{margin:.35rem 0}
.study-badge{font-size:.78rem;margin-left:.45rem;color:#a3332b}.study-badge.hard{color:#9b5a0c}.study-muted{color:#666;font-size:.9rem}
.study-masked{filter:blur(5px);user-select:none;cursor:pointer}.study-masked:focus,.study-masked:active,.study-masked.study-peek{filter:none}
.study-deck{padding:1rem;border-left:3px solid #496e99;background:#f8fafc}.study-choices{display:grid;gap:.5rem;margin:.8rem 0}.study-choice{text-align:left}.study-choice:disabled{cursor:default}.study-choice.is-right{border-color:#39704d;background:#edf7ee}.study-choice.is-wrong{border-color:#ab4038;background:#fff0ee}.study-error{color:#a3332b}.study-status{font-size:.9rem;min-height:1.4em}.study-section{margin:1.5rem 0}
@media (prefers-color-scheme:dark){
 .unit-grid h3{color:#a9c8eb}.unit-callout{background:#202b32}
 .study-item{background:#242827;border-color:#484d4a;color:#ecedeb}.study-deck{background:#202b32;color:#ecedeb}
 .study-tools input,.study-tools button,.study-bar button,.study-rates button,.study-filters button,.study-choice{background:#2d3436;color:#ecedeb;border-color:#68716e}
 .study-filters button[aria-pressed=true],.study-bar button[aria-pressed=true]{background:#7898ba;color:#101a23}
 .study-choice.is-right{background:#264332;border-color:#8ec79b;color:#f0fff2}.study-choice.is-wrong{background:#51302d;border-color:#e29c95;color:#fff2f0}
 .study-badge,.study-error,.today-focus{color:#f19d93}.study-badge.hard{color:#f2bd72}.study-muted{color:#bec6c2}.pattern,.conn,.lesson-nav a{color:#a9c8eb}
}
"""

JS = r"""
(function(){'use strict';
var PREFIX='nh80.v9.pending.', KEY='nh80.v5.access', LOCAL='nh80.v9.latest', SNAP='nh80.v9.study.snapshot', CATALOG='nh80.v9.catalog', study=read(SNAP,null),catalog=read(CATALOG,[]),busy=false,timer=null,inflight=new Set();
var $=function(s,r){return (r||document).querySelector(s)};
function esc(x){return String(x==null?'':x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function uid(){return (crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2))}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch(e){return fallback}}
function pending(){return Object.keys(localStorage).filter(function(k){return k.indexOf(PREFIX)===0}).map(function(k){var x=read(k,null);return x?{key:k,value:x}:null}).filter(Boolean)}
function mergeRows(base,rows){
 var v=JSON.parse(JSON.stringify(base||{ratings:[],questions:[],plan:null}));v.ratings=v.ratings||[];v.questions=v.questions||[];
 rows.forEach(function(entry){var x=entry.value||entry;if(x.kind==='rating'){
  var r=x.review, old=v.ratings.find(function(y){return y.kid===r.kid});
  if(!old){old={kid:r.kid,ever_bad:0};v.ratings.push(old)}
  old.ever_bad=Boolean(old.ever_bad||r.rating==='again'||r.rating==='hard');old.rating=r.rating;old.day=r.day;old.created_at=x.created_at||old.created_at;
 }else if(x.kind==='attempt' && typeof x.correct==='boolean'){
  var row=v.questions.find(function(y){return y.qid===x.result.qid&&y.day===x.day});
  if(!row && !x.correct){row={qid:x.result.qid,day:x.day,knowledge_ids:x.knowledge_ids||[],wrong_count:0};v.questions.push(row)}
  if(row){row.last_correct=x.correct?1:0;if(!x.correct)row.wrong_count=(Number(row.wrong_count)||0)+1;if(!row.knowledge_ids.length)row.knowledge_ids=x.knowledge_ids||[]}
 }});return v;
}
function currentStudy(){return mergeRows(study,pending())}
function persistStudy(value){localStorage.setItem(SNAP,JSON.stringify(value));study=value}
function tell(message,isError){document.querySelectorAll('#studyStatus').forEach(function(el){el.textContent=message;el.classList.toggle('study-error',!!isError)})}
function queue(x){var key=PREFIX+uid();try{localStorage.setItem(key,JSON.stringify(x))}catch(e){tell('本机存储已满，记录未能保存，请清理空间后重试。',true);return false}schedule();return true}
function schedule(){clearTimeout(timer);timer=setTimeout(function(){flush()},600)}
function dayFor(kid){var page=Number(document.body.dataset.day)||0;if(page>=1&&page<=150)return page;var c=catalog.find(function(x){return (x.kid||x.id)===kid});var n=Number(localStorage.getItem('nh80.v5.lastDay'))||Number(c&&c.day)||0;return n>=1&&n<=150?n:0}
function updateLatest(kid,rating){var all=read(LOCAL,{});all[kid]=rating;try{localStorage.setItem(LOCAL,JSON.stringify(all))}catch(e){};paintBadges()}
function rate(kid,rating){if(!/^[VGK]\d{4}$/.test(kid)||['again','hard','good'].indexOf(rating)<0)return false;var day=dayFor(kid);if(!day){tell('缺少学习日，暂不能保存自评；请先打开对应课程。',true);return false}var item={kind:'rating',review:{event_id:'r-'+uid(),kid:kid,day:day,rating:rating}};if(!queue(item))return false;updateLatest(kid,rating);tell('已保存在本机，等待同步。');renderPersonal();return true}
function attempt(q,answer,correct,details){details=details||{};var day=Number(q.day)||Number(document.body.dataset.day)||0;if(day<1||day>150)return false;var qid=q.qid||q.id;if(!qid)return false;
 var sessionKey='nh80.v5.session.'+day, session=sessionStorage.getItem(sessionKey);
 if(q._replay){session=q._replaySession||(q._replaySession='replay-'+uid())}
 else if(!session){session='web-'+day+'-'+uid();sessionStorage.setItem(sessionKey,session)}
 var item={kind:'attempt',day:day,session:session,correct:typeof correct==='boolean'?correct:null,knowledge_ids:Array.isArray(q.knowledge_ids)?q.knowledge_ids:[],result:{qid:qid,answer:String(answer),hinted:details.hinted===true,revealed_before_submit:details.revealed_before_submit===true,seconds:Number.isFinite(details.seconds)?Math.max(0,Math.min(86400,Math.round(details.seconds))):null}};
 if(!queue(item))return false;paintBadges();if(!$('#wrongDeck'))renderPersonal();tell('练习已保存在本机，等待同步。');return true}
async function post(path,body){var key=sessionStorage.getItem(KEY)||'';if(!key)throw Error('请先填写学习口令；待同步记录仍保存在本机。');var res=await fetch(path,{method:'POST',headers:{'content-type':'application/json','X-NH80-Key':key},body:JSON.stringify(body)});var data=await res.json().catch(function(){return {}});if(!res.ok||data.ok!==true){var msg=res.status===401?'口令不正确':res.status===429?'云端保存额度已用完':'云端暂不可用（'+(data.reason||res.status)+'）';throw Error(msg+'；记录仍保存在本机，可导出。')}return data}
async function flush(){if(busy)return;var all=pending();if(!all.length){tell('本机没有待同步记录。');return}if(!sessionStorage.getItem(KEY)){tell('待同步 '+all.length+' 条；填写学习口令后同步。',true);return}busy=true;
 try{while((all=pending()).length){var ratings=all.filter(function(x){return x.value.kind==='rating'}).slice(0,40),batch;
  if(ratings.length){await post('/api/reviews',{reviews:ratings.map(function(x){return x.value.review})});batch=ratings}
  else{var first=all.find(function(x){return x.value.kind==='attempt'});if(!first)throw Error('本机队列包含无法识别的记录，请导出。');var session=first.value.session;inflight.add(session);batch=all.filter(function(x){return x.value.kind==='attempt'&&x.value.session===session}).slice(0,40);try{await post('/api/events',{v:1,day:first.value.day,session:session,practice_mode:first.value.session.indexOf('replay-')===0?'teacher':'choice',results:batch.map(function(x){return x.value.result})})}finally{inflight.delete(session)}}
  persistStudy(mergeRows(study,batch));batch.forEach(function(x){localStorage.removeItem(x.key)});
 }tell('本机记录已同步；到期计划以会话同步时间为准。');await refresh();
 }catch(e){tell(e.message||'同步失败；记录仍保存在本机，可导出。',true)}finally{busy=false}}
function exportPending(){var rows=pending().map(function(x){return x.value});var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,exported_at:new Date().toISOString(),pending:rows},null,2)],{type:'application/json'}));a.download='nihongo-pending.json';a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},1000)}
function ratingButtons(kid){return '<div class="study-rates">'+[['again','忘了'],['hard','不熟'],['good','记得']].map(function(a){return '<button type="button" data-study-rate="'+a[0]+'" data-kid="'+esc(kid)+'">'+a[1]+'</button>'}).join('')+'</div>'}
function bindRates(root){root.querySelectorAll('[data-study-rate]').forEach(function(b){b.onclick=function(){rate(b.dataset.kid,b.dataset.studyRate)}})}
function paintBadges(){var study=currentStudy(),latest=read(LOCAL,{}),map={},focus={},recovered={};if(study){((study.plan||{}).focus||[]).forEach(function(x){if(x.kid&&Array.isArray(x.reasons))focus[x.kid]=x.reasons.join('、')});(study.questions||[]).forEach(function(q){(q.knowledge_ids||[]).forEach(function(k){map[k]='wrong'})});(study.ratings||[]).forEach(function(r){if(r.rating==='again'||r.rating==='hard')map[r.kid]=r.rating;else if(r.ever_bad){recovered[r.kid]=true;if(!map[r.kid])map[r.kid]='recovered'}})};Object.keys(latest).forEach(function(k){if(latest[k]==='again'||latest[k]==='hard')map[k]=latest[k]});document.querySelectorAll('[data-kid]').forEach(function(el){if(el.matches('button')||el.classList.contains('study-badge'))return;el.querySelectorAll(':scope > .study-badge').forEach(function(old){old.remove()});var x=map[el.dataset.kid];if(x==='again'||x==='hard'||x==='wrong'||x==='recovered'){var b=document.createElement('span');b.className='study-badge '+(x==='hard'?'hard':'');b.textContent=x==='again'?'忘了':x==='hard'?'不熟':x==='recovered'?'曾不熟 · 已复习':'曾错过';el.appendChild(b)}if(recovered[el.dataset.kid]&&x!=='recovered'){var h=document.createElement('span');h.className='study-badge hard';h.textContent='曾不熟 · 已复习';el.appendChild(h)}if(focus[el.dataset.kid]){var f=document.createElement('span');f.className='study-badge';f.textContent=focus[el.dataset.kid];el.appendChild(f)}})}
async function refresh(){try{if(!catalog.length){var cr=await fetch('/data/catalog.json');if(!cr.ok)throw Error('课程索引暂不可用');catalog=await cr.json();if(!Array.isArray(catalog))throw Error('课程索引格式错误');try{localStorage.setItem(CATALOG,JSON.stringify(catalog))}catch(e){}}var key=sessionStorage.getItem(KEY);if(key){var r=await fetch('/api/study',{headers:{'X-NH80-Key':key},cache:'no-store'});if(!r.ok)throw Error(r.status===401?'学习口令不正确':'个人记录暂不可用');persistStudy(await r.json());var latest=read(LOCAL,{});pending().filter(function(x){return x.value.kind==='rating'}).forEach(function(x){latest[x.value.review.kid]=x.value.review.rating});var pendingKids=new Set(pending().filter(function(x){return x.value.kind==='rating'}).map(function(x){return x.value.review.kid}));Object.keys(latest).forEach(function(k){if(!pendingKids.has(k))delete latest[k]});localStorage.setItem(LOCAL,JSON.stringify(latest))}paintBadges();renderPersonal()}catch(e){paintBadges();renderPersonal();tell(e.message+'；本机待同步记录不受影响。',true)}}
function fnv(t){var s=String(t==null?'':t).normalize('NFKC').replace(/\s+/g,''),h=2166136261>>>0;for(var ch of s){h^=ch.codePointAt(0);h=Math.imul(h,16777619)>>>0}return h.toString(16)}
function deck(root,questions){if(!root)return;var filter='mixed',index=0,done={};function render(){var arr=questions.filter(function(q){return filter==='mixed'||q.group===filter});if(index>=arr.length)index=Math.max(0,arr.length-1);var q=arr[index];root.innerHTML='<div class="study-filters">'+[['mixed','全部'],['vocab','词汇'],['grammar','语法']].map(function(a){return '<button type="button" data-filter="'+a[0]+'" aria-pressed="'+(filter===a[0])+'">'+a[1]+'</button>'}).join('')+'</div>'+(q?'<div class="study-deck"><div class="study-muted">'+(index+1)+' / '+arr.length+' · 自选练习</div><p>'+esc(q.prompt)+'</p><div class="study-choices">'+(q.options||[]).map(function(o,i){return '<button type="button" class="study-choice" data-choice="'+i+'">'+esc(o)+'</button>'}).join('')+'</div><div class="study-feedback" aria-live="polite"></div></div><div class="study-bar"><button type="button" data-prev>上一题</button><button type="button" data-next>下一题</button></div>':'<p class="study-muted">当前没有这类练习。</p>');root.querySelectorAll('[data-filter]').forEach(function(b){b.onclick=function(){filter=b.dataset.filter;index=0;render()}});if(!q)return;root.querySelector('[data-prev]').onclick=function(){index=Math.max(0,index-1);render()};root.querySelector('[data-next]').onclick=function(){index=Math.min(arr.length-1,index+1);render()};root.querySelectorAll('[data-choice]').forEach(function(b){b.onclick=function(){if(done[q.qid])return;var answer=q.options[Number(b.dataset.choice)],ok=fnv(answer)===String(q.h);if(!attempt(q,answer,ok)&&Number(q.day||document.body.dataset.day)>0)return;done[q.qid]={answer:answer,ok:ok};root.querySelectorAll('[data-choice]').forEach(function(x){x.disabled=true;var v=q.options[Number(x.dataset.choice)];if(fnv(v)===String(q.h))x.classList.add('is-right')});if(!ok)b.classList.add('is-wrong');root.querySelector('.study-feedback').textContent=ok?'答对了。':'还不对，正确项已标出。'}});if(done[q.qid]){var saved=done[q.qid];root.querySelectorAll('[data-choice]').forEach(function(x){x.disabled=true;var v=q.options[Number(x.dataset.choice)];if(fnv(v)===String(q.h))x.classList.add('is-right');if(!saved.ok&&v===saved.answer)x.classList.add('is-wrong')});root.querySelector('.study-feedback').textContent=saved.ok?'答对了。':'还不对，正确项已标出。'}}render()}
var mask='all',personalFilter='due';
function card(c,showRate){var kid=c.kid||c.id,front=c.front||c.surface||c.pattern||c.char||'',back=c.back||c.meaning_zh||c.meaning||'',kana=c.kana||'';return '<article class="study-item" data-kid="'+esc(kid)+'"><p><small class="study-kind">'+(c.kind==='grammar'?'语法':c.kind==='kanji'?'汉字':'词汇')+' · Day '+esc(c.day||'')+'</small><span tabindex="0" data-side="ja">'+esc(front)+(kana?'　'+esc(kana):'')+'</span></p><p><span tabindex="0" data-side="zh">'+esc(back)+'</span></p>'+(showRate?ratingButtons(kid):'')+'</article>'}
function masking(root){if(!root)return;root.querySelectorAll('[data-side]').forEach(function(el){el.classList.toggle('study-masked',mask===el.dataset.side);el.onclick=function(){el.classList.toggle('study-peek')};el.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();el.classList.toggle('study-peek')}}});root.querySelectorAll('[data-study-mask]').forEach(function(b){b.setAttribute('aria-pressed',String(mask===b.dataset.studyMask));b.onclick=function(){mask=b.dataset.studyMask;masking(root)}})}
function maskControls(){return '<div class="study-bar">'+[['all','显示全部'],['zh','遮中文'],['ja','遮日语']].map(function(x){return '<button type="button" data-study-mask="'+x[0]+'">'+x[1]+'</button>'}).join('')+'</div>'}
function renderUnit(){var root=$('#unitList'),unit=window.__UNIT__;if(!root||!unit)return;var items=unit.items||[],lastDay=0;root.innerHTML='<p class="study-muted">'+items.filter(function(c){return c.kind==='vocab'}).length+' 个词 · '+items.filter(function(c){return c.kind==='grammar'}).length+' 条语法</p>'+maskControls()+'<div class="study-list unit-grid">'+items.map(function(c){var heading=c.day!==lastDay?'<h3>Day '+c.day+'</h3>':'';lastDay=c.day;return heading+card(c,true)}).join('')+'</div>';masking(root);bindRates(root);paintBadges()}
function renderPersonal(){var root=$('#personalReview');if(!root)return;var study=currentStudy();var ratings=study&&study.ratings||[],questions=study&&study.questions||[],due=study&&study.plan&&study.plan.due||[],local=read(LOCAL,{}), ratingMap={};ratings.forEach(function(r){ratingMap[r.kid]=r.rating});Object.keys(local).forEach(function(k){ratingMap[k]=local[k]});var ids=new Set();if(personalFilter==='due')due.forEach(function(d){ids.add(d.kid)});if(personalFilter==='wrong'){questions.forEach(function(q){(q.knowledge_ids||[]).forEach(function(k){ids.add(k)})});((study&&study.plan&&study.plan.focus)||[]).forEach(function(x){if((x.reasons||[]).some(function(r){return r.indexOf('曾答错')>=0}))ids.add(x.kid)})};if(personalFilter==='hard'){Object.keys(ratingMap).forEach(function(k){if(ratingMap[k]==='again'||ratingMap[k]==='hard')ids.add(k)});((study&&study.plan&&study.plan.focus)||[]).forEach(function(x){if((x.reasons||[]).some(function(r){return r.indexOf('自评')>=0}))ids.add(x.kid)})};var items=catalog.filter(function(c){return ids.has(c.kid||c.id)});var updated=study&&study.plan&&study.plan.updated_at;
 root.innerHTML='<p class="study-muted">自评和错题是练习记录，不代表掌握。'+(updated?'到期建议最后同步：'+esc(updated):'暂无会话发布的到期计划。')+'</p><div class="study-filters">'+[['due','待复习'],['wrong','曾错过'],['hard','忘了 / 不熟']].map(function(a){return '<button type="button" data-personal-filter="'+a[0]+'" aria-pressed="'+(personalFilter===a[0])+'">'+a[1]+'</button>'}).join('')+'</div>'+maskControls()+'<div class="study-list">'+(items.length?items.map(function(c){return card(c,true)}).join(''):'<p class="study-muted">'+(!study?'填写口令并同步后查看个人记录。':'这个分类暂无记录。')+'</p>')+'</div>'+(personalFilter==='wrong'&&questions.length?'<div class="study-section"><button type="button" data-retry>复练曾错题</button><div id="wrongDeck"></div></div>':'');root.querySelectorAll('[data-personal-filter]').forEach(function(b){b.onclick=function(){personalFilter=b.dataset.personalFilter;renderPersonal()}});masking(root);bindRates(root);paintBadges();var retry=root.querySelector('[data-retry]');if(retry)retry.onclick=async function(){retry.disabled=true;try{var days=Array.from(new Set(questions.map(function(q){return q.day})));var data=await Promise.all(days.map(async function(d){var r=await fetch('/data/day-'+String(d).padStart(3,'0')+'.json');if(!r.ok)throw Error('题目暂不可用');return r.json()}));var wanted=new Set(questions.map(function(q){return q.day+':'+q.qid})),qs=[];data.forEach(function(d){[].concat(d.practice||[],d.unit_questions||[],d.quiz||[],d.sentences||[],(d.listening_material||{}).questions||[]).forEach(function(q){if(wanted.has(d.day+':'+q.qid))qs.push(Object.assign({day:d.day,group:'mixed'},q,{_replay:true}))})});if(qs.length)deck($('#wrongDeck'),qs);else $('#wrongDeck').textContent='当前版本未找到这些历史题目。'}catch(e){$('#wrongDeck').textContent=e.message}finally{retry.disabled=false}}}
function init(){var controls=$('#studySync');if(controls){controls.innerHTML='<div class="study-tools"><label>学习口令 <input type="password" autocomplete="off" id="studyAccess"></label><button type="button" id="studyFlush">同步</button><button type="button" id="studyExport">导出待同步记录</button></div><p class="study-muted">口令只保存在当前标签页；离线记录保存在本机。</p>';var input=$('#studyAccess');input.value=sessionStorage.getItem(KEY)||'';input.oninput=function(){sessionStorage.setItem(KEY,input.value.trim())};$('#studyFlush').onclick=function(){flush().then(refresh)};$('#studyExport').onclick=exportPending}deck($('#practiceDeck'),window.__PRACTICE__||((window.__UNIT__||{}).questions)||[]);renderUnit();refresh();if(pending().length){tell('本机有 '+pending().length+' 条待同步记录。');if(sessionStorage.getItem(KEY))schedule()}window.addEventListener('online',schedule)}
window.NHStudy={rate:rate,attempt:attempt,refresh:refresh,flush:flush};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
"""


def shell(title, body, day=0):
    """Render a standalone page using the site's shared study controls."""
    return ('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1">'
            '<title>' + html.escape(title) + '</title><style>' + CSS +
            '</style></head><body data-day="' + str(int(day)) + '"><main>' + body +
            '</main><script>' + JS + '</script></body></html>')
